-- The notice and the front matter that every page generated by `hecate.doc` for a project carries. Shared by
-- `hecate.doc.project` (the configuration reference) and the generation of the documentation of a project (the
-- licences page).
global <const> require, tostring

local text_helpers = require("hecate.doc.internal.text")

local M = {}

--- The notice written at the top of every generated project page.
M.GENERATED = "<!-- Generated by hecate.doc from the configuration schema of the project. "
  .. "Do not edit: change the project and build again. -->"

-- A YAML double-quoted scalar (YAML 1.2.2, 7.3.1) on one line. Control characters become a space: the
-- front matter parser of this package accepts only the escapes `\\`, `\"`, `\n` and `\t`.
local function yaml_quote(text)
  text = tostring(text):gsub("%c", " "):gsub("\\", "\\\\"):gsub('"', '\\"')
  return '"' .. text .. '"'
end

--- The lines that open a generated page: front matter, the notice and the title.
---@param title string
---@param description? string  defaults to the title
---@param order integer
---@param audience hecate.doc.Audience
---@return string[] lines
function M.front(title, description, order, audience)
  return { "---", "description: " .. yaml_quote(description or title),
    "order: " .. tostring(order), "audience: " .. audience, "---", "", M.GENERATED, "", "# " .. text_helpers.plain(title), "" }
end

return M
